(1, $json${"en":"Amit Kochavi","he":"עמית כוכבי"}$json$, $json${"en":"Business. Philanthropy. Public Service.","he":"עסקים. פילנתרופיה. שירות ציבורי."}$json$, 'office@amitkochavi.com', $json$[{"platform":"LinkedIn","url":"https://www.linkedin.com/in/amitkochavi/"},{"platform":"Starwell Holdings","url":"https://starwellholdings.com/en/"}]$json$, $json${"title":{"en":"Amit Kochavi — Business, Philanthropy & Public Service","he":"עמית כוכבי — עסקים, פילנתרופיה ושירות ציבורי"},"description":{"en":"Amit Kochavi — founder of Starwell Holdings and senior advisor to the Mayor of Sderot. Building companies and city-scale projects between Tel Aviv and Los Angeles.","he":"עמית כוכבי — מייסד סטארוול הולדינגס ויועץ בכיר לראש עיריית שדרות. בונה חברות ופרויקטים עירוניים בין תל אביב ללוס אנג'לס."}}$json$, $json${"name":"Amit Kochavi","alternateName":["Amit L. Kochavi","Amit Lev Kochavi","עמית כוכבי","עמית לב כוכבי"],"jobTitle":{"en":"Founder of Starwell Holdings; Senior Advisor to the Mayor of Sderot","he":"מייסד סטארוול הולדינגס; יועץ בכיר לראש עיריית שדרות"},"description":{"en":"Amit Kochavi is an entrepreneur and investor, the founder of Starwell Holdings, and senior advisor to the Mayor of Sderot — working between Tel Aviv and Los Angeles.","he":"עמית כוכבי הוא יזם ומשקיע, מייסד סטארוול הולדינגס ויועץ בכיר לראש עיריית שדרות — פועל בין תל אביב ללוס אנג'לס."},"sameAs":["https://www.linkedin.com/in/amitkochavi/"],"worksFor":"Starwell Holdings","knowsAbout":["Entrepreneurship","Investment","Information Technology","Real Estate","Public Service","Sderot"]}$json$)
insert into public.pages (key, title, hero, blocks, seo, sort_order) values
('home', $json${"en":"Amit Kochavi","he":"עמית כוכבי"}$json$, $json${"title":{"en":"Amit Kochavi","he":"עמית כוכבי"},"subtitle":{"en":"Founder of Starwell Holdings. Senior advisor to the Mayor of Sderot. Building between Tel Aviv and Los Angeles.","he":"מייסד סטארוול הולדינגס. יועץ בכיר לראש עיריית שדרות. בונה בין תל אביב ללוס אנג'לס."},"cta_label":{"en":"Learn more","he":"מידע נוסף"},"cta_href":"/about"}$json$, $json$[{"id":"home-pillars","type":"cards","heading":{"en":"Explore","he":"גלו עוד"},"items":[{"title":{"en":"Business","he":"עסקים"},"body":{"en":"Starwell Holdings: a technology arm buying and building Israeli IT companies, a real estate arm continuing four generations of family business, and an investments arm.","he":"סטארוול הולדינגס: זרוע טכנולוגיה שרוכשת ובונה חברות IT ישראליות, זרוע נדל\"ן שממשיכה ארבעה דורות של עסק משפחתי, וזרוע השקעות."},"href":"/business"},{"title":{"en":"Philanthropy","he":"פילנתרופיה"},"body":{"en":"Four generations of family giving in Israel and Los Angeles. Two foundation board seats.","he":"ארבעה דורות של נתינה משפחתית בישראל ובלוס אנג'לס. שני מושבי דירקטוריון."},"href":"/philanthropy"},{"title":{"en":"Public Service","he":"שירות ציבורי"},"body":{"en":"Working with the Mayor of Sderot and the Tkuma Directorate on the city's recovery since October 7th.","he":"עבודה עם ראש עיריית שדרות ומינהלת תקומה על שיקום העיר, מאז 7 באוקטובר."},"href":"/public-service"}]}]$json$, $json${"title":{"en":"Amit Kochavi — Business, Philanthropy & Public Service","he":"עמית כוכבי — עסקים, פילנתרופיה ושירות ציבורי"}}$json$, 0),
('about', $json${"en":"About","he":"אודות"}$json$, $json${"title":{"en":"About Amit Kochavi","he":"אודות עמית כוכבי"},"subtitle":{"en":"Founder of Starwell Holdings. Senior advisor to the Mayor of Sderot. Tel Aviv and Los Angeles.","he":"מייסד סטארוול הולדינגס. יועץ בכיר לראש עיריית שדרות. תל אביב ולוס אנג'לס."}}$json$, $json$[{"id":"about-short-bio","type":"text","heading":{"en":"Short bio","he":"ביו קצר"},"body":{"en":"<p>Amit Kochavi is an entrepreneur and investor, and the founder of <a href=\"https://starwellholdings.com/en/\" target=\"_blank\" rel=\"noopener\">Starwell Holdings</a> — a Tel Aviv holding company with three arms: technology, real estate, and investments. Through it he acquires and builds Israeli IT services companies, continues his family's fourth-generation real estate business — residential, logistics, commercial, and office properties in Israel and the United States — and advises on large urban projects, including Rova 7, an 890-home development in Jaffa. Since October 2023 he has served as senior advisor to the Mayor of Sderot, working with the Tkuma Directorate in the Prime Minister's Office on the city's recovery — including a new ₪500M technology faculty at Sapir Academic College and a ₪100M program relocating tech families to the region. He founded his first company, Cormi, at 21, and serves on the boards of the Buchman Heyman Foundation and the Herb &amp; Sharon Glaser Foundation. A descendant of Max Factor Sr., he is a member of Voice of the People, the President of Israel's council on the future of the Jewish people, and lives between Tel Aviv and Los Angeles.</p>","he":"<p>עמית כוכבי הוא יזם ומשקיע, מייסד <a href=\"https://starwellholdings.com/he/\" target=\"_blank\" rel=\"noopener\">סטארוול הולדינגס</a> (Starwell Holdings) — חברת אחזקות תל־אביבית עם שלוש זרועות: טכנולוגיה, נדל\"ן והשקעות. דרכה הוא רוכש ובונה חברות שירותי IT בישראל, ממשיך את עסקי הנדל\"ן המשפחתיים זה ארבעה דורות — מגורים, לוגיסטיקה, מסחר ומשרדים בישראל ובארה\"ב — ומלווה פרויקטים עירוניים גדולים, בהם רובע 7 ביפו, פרויקט של כ-890 יחידות דיור. מאז אוקטובר 2023 הוא משמש יועץ בכיר לראש עיריית שדרות ופועל עם מינהלת תקומה במשרד ראש הממשלה על שיקום העיר וצמיחתה — בין היתר פקולטה חדשה לטכנולוגיה במכללה האקדמית ספיר בתקציב של כ-500 מיליון ש\"ח, ותוכנית של 100 מיליון ש\"ח להעברת משפחות הייטק לאזור. את החברה הראשונה שלו, Cormi, הקים בגיל 21, והוא חבר דירקטוריון בקרן בוכמן־היימן ובקרן הרברט ושרון גלייזר. צאצא של מקס פקטור האב, חבר ב\"קול העם\" — מועצת נשיא המדינה לעתיד העם היהודי — וחי בין תל אביב ללוס אנג'לס.</p>"}},{"id":"about-story","type":"text","heading":{"en":"My story","he":"הסיפור שלי"},"body":{"en":"<p>I was born in Tel Aviv on December 10, 1997, and grew up between Tel Aviv and Los Angeles.</p>\n<p>I'm a fourth-generation entrepreneur. Real estate is the family business: four generations of developing and owning residential, logistics, commercial, and office properties in Israel and the United States. One side of my family also goes back to Max Factor Sr., who left Łódź with a trade, opened a shop in Los Angeles, and turned his own name into one of the best-known brands in the world. The rule I grew up on: what you inherit matters less than what you build yourself.</p>\n<p>In March 2019, at 21, I founded my first company, Circles. We launched an innovation-management platform, sold it to our first customers, and failed. We rebuilt the company as Cormi — a forms and workflow platform for construction and manufacturing businesses — backed by Israeli investors, including the owner of Tidhar, one of Israel's largest construction groups. Cormi is still running today.</p>\n<p>Now I run <a href=\"https://starwellholdings.com/en/\" target=\"_blank\" rel=\"noopener\">Starwell Holdings</a>, built around three arms. The technology arm acquires established Israeli IT services companies — profitable businesses with 20 to 50 employees — and upgrades them with AI. The real estate arm continues the family business and advises on large urban projects; right now, Rova 7 in Jaffa: about 890 homes and commercial space, developed by Kardan Real Estate and Realty Fund. The investments arm manages the group's capital in Israel and the U.S. The full picture is on the <a href=\"/en/business\">Business page</a>.</p>\n<p>October 7, 2023 changed my direction. Since then I've served as senior advisor to the Mayor of Sderot, working with the Tkuma Directorate in the Prime Minister's Office on the city's recovery and growth: a new ₪500M technology faculty at Sapir Academic College, a ₪100M program bringing tech families to the region, a Rimon music school, and seven bilingual kindergartens. The details are on the <a href=\"/en/public-service\">Public Service page</a>. It's the most meaningful work I've done.</p>\n<p>Alongside that, I serve on the boards of two of my family's foundations — the Buchman Heyman Foundation, founded in 1942, and the Herb &amp; Sharon Glaser Foundation — and I'm a member of TAU Aurion, Tel Aviv University's next-generation leadership community, and of Voice of the People, the President of Israel's council on the future of the Jewish people.</p>\n<p>I believe in free markets, strong security, a pluralistic Israel, and a close bond between Israel and Jewish communities around the world. And I believe the way to lead in Israel is to do the work first.</p>","he":"<p>נולדתי בתל אביב ב-10 בדצמבר 1997, וגדלתי בין תל אביב ללוס אנג'לס.</p>\n<p>אני דור רביעי של יזמים. נדל\"ן הוא העסק המשפחתי: ארבעה דורות של יזמות ובעלות בתחומי המגורים, הלוגיסטיקה, המסחר והמשרדים — בישראל ובארצות הברית. צד אחד של המשפחה גם מגיע עד מקס פקטור האב, שעזב את לודז' עם מקצוע ביד, פתח חנות בלוס אנג'לס, והפך את השם הפרטי שלו לאחד המותגים המוכרים בעולם. הכלל שגדלתי עליו: מה שאתה יורש חשוב פחות ממה שאתה בונה בעצמך.</p>\n<p>במרץ 2019, בגיל 21, הקמתי את החברה הראשונה שלי, Circles. השקנו פלטפורמה לניהול חדשנות, מכרנו ללקוחות הראשונים — ונכשלנו. בנינו את החברה מחדש כ-Cormi, פלטפורמת טפסים ותהליכי עבודה לחברות בנייה וייצור, בגיבוי משקיעים ישראלים ובהם הבעלים של תדהר, מקבוצות הבנייה הגדולות בישראל. Cormi פועלת עד היום.</p>\n<p>היום אני מנהל את <a href=\"https://starwellholdings.com/he/\" target=\"_blank\" rel=\"noopener\">סטארוול הולדינגס</a>, שבנויה משלוש זרועות. זרוע הטכנולוגיה רוכשת חברות שירותי IT ותיקות בישראל — עסקים רווחיים עם 20 עד 50 עובדים — ומשדרגת אותן עם AI. זרוע הנדל\"ן ממשיכה את העסק המשפחתי ומלווה פרויקטים עירוניים גדולים; כרגע — רובע 7 ביפו: כ-890 יחידות דיור ושטחי מסחר, של קרדן נדל\"ן וריאליטי קרן השקעות. זרוע ההשקעות מנהלת את ההון של הקבוצה בישראל ובארה\"ב. התמונה המלאה בעמוד <a href=\"/he/business\">עסקים</a>.</p>\n<p>7 באוקטובר 2023 שינה את הכיוון שלי. מאז אני יועץ בכיר לראש עיריית שדרות, ועובד עם מינהלת תקומה במשרד ראש הממשלה על השיקום והצמיחה של העיר: פקולטה חדשה לטכנולוגיה במכללה האקדמית ספיר בתקציב של כ-500 מיליון ש\"ח, תוכנית של 100 מיליון ש\"ח להבאת משפחות הייטק לאזור, בית ספר למוזיקה של רימון, ושבעה גני ילדים דו־לשוניים. הפרטים בעמוד <a href=\"/he/public-service\">שירות ציבורי</a>. זו העבודה המשמעותית ביותר שעשיתי.</p>\n<p>לצד זה אני חבר דירקטוריון בשתיים מקרנות המשפחה — קרן בוכמן־היימן, שנוסדה ב-1942, וקרן הרברט ושרון גלייזר — וחבר ב-TAU Aurion, קהילת המנהיגות הצעירה של אוניברסיטת תל אביב, וב\"קול העם\", מועצת נשיא המדינה לעתיד העם היהודי.</p>\n<p>אני מאמין בשוק חופשי, בביטחון חזק, בישראל פלורליסטית ובקשר הדוק בין ישראל לקהילות היהודיות בעולם. ואני מאמין שהדרך להנהיג בישראל היא קודם כול לעשות את העבודה.</p>"}}]$json$, $json${}$json$, 1),
('business', $json${"en":"Business","he":"עסקים"}$json$, $json${"title":{"en":"Business","he":"עסקים"},"subtitle":{"en":"One holding company. Three arms: technology, real estate, investments.","he":"חברת אחזקות אחת. שלוש זרועות: טכנולוגיה, נדל\"ן, השקעות."}}$json$, $json$[{"id":"biz-opening","type":"text","body":{"en":"<p><a href=\"https://starwellholdings.com/en/\" target=\"_blank\" rel=\"noopener\">Starwell Holdings</a> is my holding company, based in Tel Aviv. Three arms — technology, real estate, and investments — alongside Cormi, the company I founded at 21.</p>","he":"<p><a href=\"https://starwellholdings.com/he/\" target=\"_blank\" rel=\"noopener\">סטארוול הולדינגס</a> היא חברת האחזקות שלי, יושבת בתל אביב. שלוש זרועות — טכנולוגיה, נדל\"ן והשקעות — לצד Cormi, החברה שהקמתי בגיל 21.</p>"}},{"id":"biz-technology","type":"text","heading":{"en":"The technology arm — buying and building Israeli IT companies","he":"זרוע הטכנולוגיה — רכישה ובנייה של חברות IT ישראליות"},"body":{"en":"<p>Through Starwell's technology arm, we acquire established IT services and managed services (MSP) companies in Israel.</p>\n<p>What we look for:</p>\n<ul><li>Revenue of ₪10–30 million and 20–50 employees</li><li>Long-standing business clients on recurring service contracts</li><li>Owners planning retirement or their next chapter</li></ul>\n<p>The thesis: these are good businesses run the old way. AI is changing how much a service team can deliver per person, and what clients will ask of their IT provider. We buy the company, keep the team and the clients, and upgrade the operation — automation inside, and new lines for the existing client base: ERP and CRM implementation, AI agents, and cybersecurity.</p>\n<p>We buy to own and operate for the long term — not to flip.</p>\n<p>If you own an Israeli IT services company and the next chapter is on your mind, I want to hear from you. <a href=\"/en/contact\">Contact me →</a></p>","he":"<p>דרך זרוע הטכנולוגיה של סטארוול אנחנו רוכשים חברות ותיקות לשירותי IT ושירותים מנוהלים (MSP) בישראל.</p>\n<p>מה אנחנו מחפשים:</p>\n<ul><li>הכנסות של 10–30 מיליון ש\"ח ו-20–50 עובדים</li><li>לקוחות עסקיים ותיקים בחוזי שירות מתמשכים</li><li>בעלים שמתכננים פרישה או פרק הבא</li></ul>\n<p>התזה: אלה עסקים טובים שמנוהלים בשיטה הישנה. ה-AI משנה כמה צוות שירות יכול לספק לכל עובד, ומה לקוחות יבקשו מספק ה-IT שלהם. אנחנו קונים את החברה, שומרים על הצוות ועל הלקוחות, ומשדרגים את התפעול — אוטומציה בפנים, וקווי מוצר חדשים ללקוחות הקיימים: הטמעות ERP ו-CRM, סוכני AI, וסייבר.</p>\n<p>אנחנו קונים כדי להחזיק ולתפעל לטווח ארוך — לא כדי למכור הלאה.</p>\n<p>יש לך חברת שירותי IT בישראל, והפרק הבא על השולחן? דברו איתי. <a href=\"/he/contact\">צור קשר ←</a></p>"}},{"id":"biz-realestate","type":"text","heading":{"en":"The real estate arm — the family business, fourth generation","he":"זרוע הנדל\"ן — העסק המשפחתי, דור רביעי"},"body":{"en":"<p>Real estate is my family's business. Four generations of developing and owning residential, logistics, commercial, and office properties — in Israel and the United States. Today the arm works on the family's projects and advises developers on large, complex urban projects.</p>\n<p>Current engagement: Rova 7 — the HaPalach compound in Givat Herzl, Jaffa. Around 890 homes plus commercial space, developed by Kardan Real Estate and Realty Fund, with construction starting in 2027. My scope: work with the municipality, project branding, the commercial mix, and how technology is built into the project.</p>","he":"<p>נדל\"ן הוא העסק של המשפחה שלי. ארבעה דורות של יזמות ובעלות בנכסי מגורים, לוגיסטיקה, מסחר ומשרדים — בישראל ובארצות הברית. היום הזרוע עובדת על הפרויקטים של המשפחה ומלווה יזמים בפרויקטים עירוניים גדולים ומורכבים.</p>\n<p>הפרויקט הנוכחי: רובע 7 — מתחם הפלח בגבעת הרצל, יפו. כ-890 יחידות דיור ושטחי מסחר, של קרדן נדל\"ן וריאליטי קרן השקעות, עם תחילת בנייה ב-2027. תחומי האחריות שלי: העבודה מול העירייה, מיתוג הפרויקט, התמהיל המסחרי, ושילוב הטכנולוגיה בפרויקט.</p>"}},{"id":"biz-investments","type":"text","heading":{"en":"The investments arm","he":"זרוע ההשקעות"},"body":{"en":"<p>The investments arm manages the group's capital: public markets and private positions, in Israel and the United States, held for the long term.</p>","he":"<p>זרוע ההשקעות מנהלת את ההון של הקבוצה: שוק ההון ופוזיציות פרטיות, בישראל ובארצות הברית, לטווח ארוך.</p>"}},{"id":"biz-cormi","type":"text","heading":{"en":"Cormi (Circles Ltd.) — my first company","he":"Cormi (Circles Ltd.) — החברה הראשונה שלי"},"body":{"en":"<p>Founded in March 2019, when I was 21. We started with an innovation-management platform, sold it, and failed — then rebuilt the company as Cormi, a forms and workflow platform for construction and manufacturing businesses. Investors include the owner of Tidhar, one of Israel's largest construction groups. Cormi is also the exclusive Israel partner of Doss, an American AI-native ERP.</p>","he":"<p>נוסדה במרץ 2019, כשהייתי בן 21. התחלנו עם פלטפורמה לניהול חדשנות, מכרנו — ונכשלנו. בנינו את החברה מחדש כ-Cormi, פלטפורמת טפסים ותהליכי עבודה לחברות בנייה וייצור. בין המשקיעים: הבעלים של תדהר, מקבוצות הבנייה הגדולות בישראל. Cormi היא גם השותפה הבלעדית בישראל של Doss, חברת ERP אמריקאית מבוססת AI.</p>"}},{"id":"biz-facts","type":"stat","items":[{"value":{"en":"4","he":"4"},"label":{"en":"Generations in real estate","he":"דורות בנדל\"ן"}},{"value":{"en":"₪10–30M","he":"10–30 מ׳"},"label":{"en":"Revenue range we acquire","he":"טווח ההכנסות שאנחנו רוכשים"}},{"value":{"en":"890","he":"890"},"label":{"en":"Homes in the current advisory project","he":"יחידות דיור בפרויקט הליווי הנוכחי"}}]}]$json$, $json${}$json$, 2),
('philanthropy', $json${"en":"Philanthropy","he":"פילנתרופיה"}$json$, $json${"title":{"en":"Philanthropy","he":"פילנתרופיה"},"subtitle":{"en":"Four generations. Two board seats.","he":"ארבעה דורות. שני מושבי דירקטוריון."}}$json$, $json$[{"id":"phil-opening","type":"text","body":{"en":"<p>My family has been giving for four generations — in Israel and in Los Angeles. I grew up with it as a responsibility, not a title: board meetings, budgets, grant decisions, and follow-through. Today I serve on the boards of two of our family foundations.</p>","he":"<p>המשפחה שלי נותנת כבר ארבעה דורות — בישראל ובלוס אנג'לס. גדלתי על זה כאחריות, לא כתואר: ישיבות דירקטוריון, תקציבים, החלטות על מענקים, ומעקב עד הסוף. היום אני חבר דירקטוריון בשתיים מקרנות המשפחה.</p>"}},{"id":"phil-foundations","type":"cards","heading":{"en":"Our family foundations","he":"קרנות המשפחה שלנו"},"items":[{"title":{"en":"The Buchman Heyman Foundation","he":"קרן בוכמן־היימן"},"body":{"en":"Founded in 1942 by Sara Buchman. I serve on the board.","he":"נוסדה ב-1942 על ידי שרה בוכמן. אני חבר דירקטוריון."}},{"title":{"en":"The Herb & Sharon Glaser Foundation","he":"קרן הרברט ושרון גלייזר"},"body":{"en":"Established in Los Angeles by my grandparents, Herbert and Sharon Glaser. I serve on the board.","he":"הוקמה בלוס אנג'לס על ידי סבי וסבתי, הרברט ושרון גלייזר. אני חבר דירקטוריון."}},{"title":{"en":"The Max Factor Family Foundation","he":"קרן משפחת מקס פקטור"},"body":{"en":"Our family's foundation in Los Angeles, continuing giving that began with Max Factor Sr.","he":"קרן המשפחה בלוס אנג'לס, שממשיכה נתינה שהתחילה אצל מקס פקטור האב."}},{"title":{"en":"TAU Aurion","he":"TAU Aurion"},"body":{"en":"I'm a member of Aurion, Tel Aviv University's next-generation leadership community.","he":"אני חבר ב-Aurion, קהילת המנהיגות הצעירה של אוניברסיטת תל אביב."}}]}]$json$, $json${}$json$, 3),
('public-service', $json${"en":"Public Service","he":"שירות ציבורי"}$json$, $json${"title":{"en":"Public Service","he":"שירות ציבורי"},"subtitle":{"en":"Sderot. Since October 7th.","he":"שדרות. מאז 7 באוקטובר."}}$json$, $json$[{"id":"ps-opening","type":"text","body":{"en":"<p>After October 7, 2023, I joined the Mayor of Sderot as a senior advisor. I work with city hall and with the Tkuma Directorate in the Prime Minister's Office on the city's recovery and growth. The job in practice: turning ideas into funded, running projects — planning, budgets, government offices, donors, execution.</p>","he":"<p>אחרי 7 באוקטובר 2023 הצטרפתי לראש עיריית שדרות כיועץ בכיר. אני עובד עם העירייה ועם מינהלת תקומה במשרד ראש הממשלה על השיקום והצמיחה של העיר. העבודה בפועל: להפוך רעיונות לפרויקטים מתוקצבים ורצים — תכנון, תקציבים, משרדי ממשלה, תורמים, ביצוע.</p>"}},{"id":"ps-projects","type":"cards","heading":{"en":"Projects since October 7th","he":"פרויקטים מאז 7 באוקטובר"},"items":[{"title":{"en":"Faculty of Technology, Sapir Academic College","he":"פקולטה לטכנולוגיה, המכללה האקדמית ספיר"},"body":{"en":"Part of the founding team of a new technology faculty in Sderot — a 15,000 m² (≈161,500 sq ft) campus next to the train station, with a budget of about ₪500 million.","he":"חלק מהצוות המקים של פקולטה חדשה לטכנולוגיה בשדרות — קמפוס של 15,000 מ\"ר (כ-161,500 רגל רבוע) ליד תחנת הרכבת, בתקציב של כ-500 מיליון ש\"ח."}},{"title":{"en":"Tech relocation to Sderot and the Gaza Envelope","he":"רילוקיישן הייטק לשדרות ולעוטף"},"body":{"en":"A ₪100 million program bringing tech workers and their families from central Israel to the region — more than 400 families.","he":"תוכנית של 100 מיליון ש\"ח להבאת עובדי הייטק ומשפחותיהם ממרכז הארץ לאזור — יותר מ-400 משפחות."}},{"title":{"en":"Rimon Music School","he":"בית ספר למוזיקה רימון"},"body":{"en":"A new Rimon music school in Sderot, with a budget of about ₪30 million.","he":"בית ספר חדש למוזיקה של רימון בשדרות, בתקציב של כ-30 מיליון ש\"ח."}},{"title":{"en":"Seven bilingual kindergartens","he":"שבעה גני ילדים דו־לשוניים"},"body":{"en":"Seven Hebrew–English kindergartens across the city.","he":"שבעה גנים בעברית ובאנגלית ברחבי העיר."}},{"title":{"en":"Voice of the People","he":"קול העם"},"body":{"en":"Beyond Sderot: I'm a member of Voice of the People, the President of Israel's council on the future of the Jewish people, which brings together members from Israel and Jewish communities around the world.","he":"מעבר לשדרות: אני חבר ב\"קול העם\", מועצת נשיא המדינה לעתיד העם היהודי, שמפגישה חברים מישראל ומקהילות יהודיות ברחבי העולם."}}]},{"id":"ps-closing","type":"text","body":{"en":"<p>This is the longest-term work I do, and the most important.</p>","he":"<p>זו העבודה הכי ארוכת־טווח שאני עושה — והכי חשובה.</p>"}}]$json$, $json${}$json$, 4),
('contact', $json${"en":"Contact","he":"צור קשר"}$json$, $json${"title":{"en":"Get in touch","he":"יצירת קשר"},"subtitle":{"en":"For media, speaking, and partnership enquiries.","he":"לפניות תקשורת, הרצאות ושיתופי פעולה."}}$json$, $json$[{"id":"contact-intro","type":"text","body":{"en":"Please use the form below or reach out by email. Messages are reviewed by Amit Kochavi’s office.","he":"ניתן להשתמש בטופס שלהלן או לפנות בדוא\"ל. ההודעות מטופלות על ידי משרדו של עמית כוכבי."}}]$json$, $json${}$json$, 5)
